function restoreCart(){try{const saved=JSON.parse(localStorage.getItem(cartStorageKey)||'[]');if(!Array.isArray(saved))return;state.cart=saved.map(item=>Number(item.id)).filter(Number.isFinite);state.cartDetails=Object.fromEntries(saved.map(item=>[Number(item.id),{quantity:Math.max(1,Number(item.quantity)||1),size:item.size||null,color:item.color||'Не указан'}]));}catch(error){state.cart=[];state.cartDetails={};}}
function persistCart(){const saved=state.cart.map(id=>({id,...(state.cartDetails[id]||{quantity:1,size:null,color:'Не указан'})}));localStorage.setItem(cartStorageKey,JSON.stringify(saved));}
