function header(back=false){const leading=back?`<button class="icon-btn" data-action="back" aria-label="Назад">${icons.back}</button>`:`<span aria-hidden="true"></span>`;return `<header class="header ${back?'page-header':'home-header'}">${leading}<button class="header__logo" data-page="home">by.adigyuzelov</button><div class="header__actions"></div></header>`;}
function listingTitle(){if(state.listingMode==='brand')return `Все товары ${state.listingBrand}`;if(state.listingMode==='category')return state.listingCategory;return ({'Пальто':'Мужские пальто','Кожаные куртки':'Мужские кожаные куртки','Бомберы':'Мужские бомберы','Ветровки':'Мужские ветровки'})[state.listingLabel]||state.listingCategory||state.listingLabel||'Каталог';}
function catalogHeader(){return `<header class="header catalog-header"><button class="icon-btn" data-action="back">${icons.back}</button><strong>${listingTitle()}</strong><div class="header__actions"><button class="icon-btn" data-page="search">${icons.search}</button></div></header>`;}
function cartHeader(){return `<header class="header catalog-header cart-header"><button class="icon-btn" data-action="back" aria-label="Назад">${icons.back}</button><strong>Корзина</strong><div class="header__actions"></div></header>`;}
function menHeader(){return `<header class="men-header"><span></span><button class="men-brand" data-page="catalog">by.adigyuzelov</button><span></span></header>`;}
function activeNavPage(page=state.page){if(['catalog','listing','product'].includes(page))return 'catalog';if(['cart','checkout','order-success'].includes(page))return 'cart';if(page==='support')return 'support';return 'home';}
function nav(){const activePage=activeNavPage();const activeIndex=navPages.indexOf(activePage);const fromIndex=navVisualIndex??activeIndex;const items=[['home','Главная'],['catalog','Каталог'],['cart','Корзина'],['support','Сервис']];const curve='M0 0C10 0 16 10 18 24C21 47 31 61 50 61C69 61 79 47 82 24C84 10 90 0 100 0';return `<nav class="bottom-nav" data-nav-index="${activeIndex}" style="--nav-index:${fromIndex}"><span class="bottom-nav__indicator" aria-hidden="true"><svg viewBox="0 0 100 64" preserveAspectRatio="none"><defs><radialGradient id="nav-inset-gradient" cx="50%" cy="64%" r="68%"><stop offset="0" stop-color="#eeeeea"/><stop offset=".52" stop-color="#d9d9d3"/><stop offset="1" stop-color="#b9b9b2"/></radialGradient><clipPath id="nav-inset-clip"><path d="${curve}H0Z"/></clipPath><filter id="nav-inset-blur"><feGaussianBlur stdDeviation="1.8"/></filter></defs><path class="indicator-fill" d="${curve}H0Z"/><path class="indicator-edge" d="${curve}H0Z"/><path class="indicator-highlight" d="${curve}H0Z"/></svg></span>${items.map(([p,l])=>`<button class="${activePage===p?'active':''}" data-page="${p}" ${activePage===p?'aria-current="page"':''}>${navIcons[p]}<span>${l}</span>${p==='cart'&&state.cart.length?`<span class="dot"></span>`:''}</button>`).join('')}</nav>`;}
function priceRequestButton(p){const requested=state.priceRequests.has(p.id);return `<button class="price-request ${requested?'is-requested':''}" data-request-price="${p.id}" ${requested?'disabled':''}>${requested?'Цена запрошена':'Узнать цену'}</button>`;}
function productCards(items=products){if(!items.length)return `<div class="search-suggestions"><p class="search-empty">Загружаем каталог…</p></div>`;return `<div class="product-grid">${items.map(p=>`<article class="product-card" data-product="${p.id}"><div class="product-card__image"><img src="${p.image}" alt="${p.name}" loading="lazy"></div><div class="product-card__copy"><p class="product-card__brand">${p.brand}</p><p class="product-card__name">${p.name}</p>${priceRequestButton(p)}</div></article>`).join('')}</div>`;}
function categoryProductCards(items){return `<div class="product-grid category-product-grid">${items.map(p=>`<article class="product-card category-product-card" data-product="${p.id}"><div class="product-card__image"><img src="${p.image}" alt="${p.name}" loading="eager"></div><div class="product-card__copy"><p class="product-card__brand">${p.brand}</p><p class="product-card__name">${p.name}</p>${priceRequestButton(p)}</div></article>`).join('')}</div>`;}

function catalogToolbar(){const filterIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round"><path d="M4 7h10M18 7h2M4 17h2M10 17h10"/><circle cx="16" cy="7" r="2"/><circle cx="8" cy="17" r="2"/></svg>';const sortLabel=state.sort==='Сначала дороже'?'Дороже':'Сортировка';return `<div class="catalog-toolbar"><label class="catalog-toolbar__search">${icons.search}<input class="catalog-search-input" value="${state.query}" placeholder="Найти товар или бренд" aria-label="Поиск по товарам"></label><button class="catalog-toolbar__action ${state.sort==='Сначала дороже'?'is-active':''}" data-action="sort" aria-label="${sortLabel}">${icons.sort}<span>${sortLabel}</span></button><button class="catalog-toolbar__action" data-action="filter" aria-label="Фильтр">${filterIcon}<span>Фильтр</span></button></div>`;}
function home(){const q=state.query.trim().toLowerCase();const visible=q?products.filter(p=>`${p.brand} ${p.name} ${p.category}`.toLowerCase().includes(q)):products;const results=visible.length?productCards(visible):`<p class="search-empty search-empty--result">Ничего не найдено</p>`;return `${header()}${catalogToolbar()}<main class="home-catalog">${results}</main>${nav()}${state.drawer?filterDrawer():''}`;}
