function categoryStrip(title,items){const canScroll=items.length>3;return `<section class="catalog-category"><h1>${title}</h1><div class="catalog-category__track">${items.map(cat=>{const media=`<div class="catalog-category__media"><img src="${cat.image}" alt="${cat.name}" loading="eager" decoding="sync" draggable="false"></div>`;return `<a class="catalog-category__card" href="?page=listing&category=${encodeURIComponent(cat.name)}" data-listing-category="${cat.name}">${media}<span>${cat.name}</span></a>`;}).join('')}</div>${canScroll?`<div class="catalog-category__hint"><span></span><small>Листайте</small></div>`:''}</section>`;}
function catalog(){const sections=approvedCategoryGroups.map(group=>{const items=group.categories.map(name=>({name,image:categoryCoverFallback[name]}));return categoryStrip(group.name,items);}).join('');return `${menHeader()}<main class="men-store category-store">${sections}</main>${nav()}`;}
function listingProducts(){const q=state.query.trim().toLowerCase();const scoped=state.listingMode==='brand'?products.filter(p=>p.brand===state.listingBrand):state.listingMode==='category'?products.filter(p=>p.category===state.listingCategory):products.filter(p=>p.label===state.listingLabel);return scoped.filter(p=>!q||`${p.brand} ${p.name} ${p.category} ${p.label}`.toLowerCase().includes(q));}
function productCountLabel(count){const mod10=count%10,mod100=count%100;if(mod10===1&&mod100!==11)return `${count} товар`;if(mod10>=2&&mod10<=4&&(mod100<12||mod100>14))return `${count} товара`;return `${count} товаров`;}
function listing(){const items=listingProducts();return `${catalogHeader()}<main class="catalog-page outerwear-listing">${catalogToolbar()}<p class="catalog-count">${productCountLabel(items.length)}</p>${items.length?categoryProductCards(items):`<p class="search-empty search-empty--result">Ничего не найдено</p>`}</main>${nav()}${state.drawer?filterDrawer():''}`;}
function search(){const q=state.query.trim().toLowerCase();const found=q?products.filter(p=>`${p.brand} ${p.name} ${p.category}`.toLowerCase().includes(q)):[];return `${header(true)}<main class="search-page"><div class="search-input-wrap"><input class="search-input" autofocus value="${state.query}" placeholder="Поиск"><button class="icon-btn" data-action="clear-search">${state.query?icons.close:icons.search}</button></div>${q?(found.length?productCards(found):`<p class="search-empty search-empty--result">Ничего не найдено</p>`):''}</main>${nav()}`;}
function productGalleryImages(p){const own=Array.isArray(p.images)?p.images:[p.image];const alternates=productAlternateImages[p.id]||[];return [...new Set([...own,...alternates].filter(Boolean))].slice(0,4);}
function productColorName(index){return ['Серый','Чёрный','Графитовый','Тёмно-синий','Коричневый'][index]||'Чёрный';}
function currentProductColor(p){const variants=products.filter(item=>item.category===p.category).slice(0,5);return productColorName(Math.max(0,variants.findIndex(item=>item.id===p.id)));}
function productProfile(p){
  const name=`${p.name} ${p.label||''}`.toLowerCase();
  if(name.includes('пальто'))return {description:'Пальто прямого кроя с чистой линией плеча и аккуратной однобортной застёжкой. Плотная шерстяная ткань держит форму, а спокойный силуэт легко сочетается с деловой и повседневной одеждой.',material:'Шерсть 80%; полиамид 20%; подкладка — вискоза',fit:'Прямой крой',details:'Средняя длина'};
  if(name.includes('кожан'))return {description:'Куртка из мягкой натуральной кожи с лаконичной застёжкой и воротником-стойкой. Минимум декора подчёркивает фактуру материала, а лёгкая подкладка делает модель удобной для межсезонья.',material:'Натуральная кожа 100%; подкладка — вискоза',fit:'Стандартная посадка',details:'Длина до бедра'};
  if(name.includes('бомбер'))return {description:'Лёгкий бомбер с эластичными манжетами и поясом. Форма сохраняет свободу движения, а гладкая ткань защищает от прохладного ветра и подходит для ежедневных городских комплектов.',material:'Полиэстер 100%; подкладка — полиэстер',fit:'Свободная посадка',details:'Укороченная длина'};
  if(name.includes('ветров')||name.includes('полев'))return {description:'Функциональная куртка для переменчивой погоды. Высокий воротник, лёгкая ткань и удобные карманы сохраняют практичность модели без лишнего объёма.',material:'Хлопок 62%; полиэстер 38%',fit:'Стандартная посадка',details:'Длина до бедра'};
  if(name.includes('джинс'))return {description:'Прямые джинсы из плотного хлопкового денима. Небольшое количество эластана добавляет комфорта, сохраняя чёткую форму и классическую посадку.',material:'Хлопок 98%; эластан 2%',fit:'Прямая посадка',details:'Средняя высота талии'};
  if(name.includes('брюк')||name.includes('карго'))return {description:'Брюки с выверенными пропорциями и комфортной посадкой. Чистая линия делает модель универсальной, а практичные карманы подходят для повседневного гардероба.',material:name.includes('шерст')?'Шерсть 96%; эластан 4%':'Хлопок 97%; эластан 3%',fit:name.includes('карго')?'Свободная посадка':'Прямая посадка',details:'Средняя высота талии'};
  if(name.includes('рубаш'))return {description:'Рубашка из дышащего хлопка с аккуратным воротником и ровной линией низа. Мягкая ткань комфортна в течение дня и сохраняет опрятный вид.',material:'Хлопок 100%',fit:'Стандартная посадка',details:'Обычная длина'};
  if(name.includes('футбол'))return {description:'Базовая футболка из плотного гладкого хлопка. Прямой силуэт, мягкая горловина и чистая обработка швов делают её удобной основой повседневного гардероба.',material:'Хлопок 100%',fit:'Прямая посадка',details:'Обычная длина'};
  if(shoeCategories.has(p.category))return {description:'Пара выполнена из сочетания кожи и прочного текстиля. Мягкая внутренняя отделка поддерживает стопу, а гибкая резиновая подошва подходит для ежедневной носки.',material:'Кожа; текстиль; резина',fit:'Соответствует размеру',details:'Стандартная полнота'};
  if(p.category==='Часы')return {description:'Часы с лаконичным циферблатом и удобным ремешком. Сдержанный корпус подходит как к деловому, так и к повседневному образу.',material:'Нержавеющая сталь; минеральное стекло',fit:'Регулируемый ремешок',details:'Универсальный размер'};
  if(p.category==='Очки')return {description:'Солнцезащитные очки с лёгкой оправой и выразительной геометрией. Затемнённые линзы подходят для ежедневного использования в городе.',material:'Ацетат; поликарбонат',fit:'Средняя ширина оправы',details:'Универсальный размер'};
  if(name.includes('ремень'))return {description:'Классический ремень из гладкой натуральной кожи с лаконичной металлической пряжкой. Сдержанная отделка подходит для брюк и денима.',material:'Натуральная кожа; металл',fit:'Регулируемый размер',details:'Ширина 3,5 см'};
  if(name.includes('сумк')||name.includes('рюкзак'))return {description:'Вместительная городская модель с продуманными отделениями и прочной фурнитурой. Лаконичная форма подходит для работы и ежедневных поездок.',material:'Текстиль; натуральная кожа; металл',fit:'Регулируемые ремни',details:'Формат для города'};
  return {description:'Модель с чистым силуэтом и аккуратной обработкой деталей. Универсальная форма подходит для современного повседневного гардероба.',material:'Комбинированные материалы',fit:'Стандартная посадка',details:'Обычная длина'};
}
function productDescription(p){return productProfile(p).description;}
function productMaterial(p){return productProfile(p).material;}
function productSizes(p){if(shoeCategories.has(p.category))return ['38','39','40','41','42','43','44'];if(clothingCategories.has(p.category))return ['S','M','L','XL','XXL'];return ['Единый'];}
function defaultProductSize(p){return shoeCategories.has(p.category)?'41':clothingCategories.has(p.category)?'M':'Единый';}
function brandDescription(brand){return ({LIGNE:'LIGNE строит мужской гардероб вокруг точного кроя, спокойных цветов и вещей, которые легко сочетать между собой.',ATELIER:'ATELIER соединяет классические формы с современными материалами. В коллекции главное — посадка, фактура и практичные детали.',SELECTED:'SELECTED собирает функциональные аксессуары и обувь для повседневного города — без лишнего декора и с вниманием к материалам.'})[brand]||`${brand} создаёт современную мужскую одежду с акцентом на качество материалов и удобную посадку.`;}
function productTabPanel(p){
  const variants=products.filter(item=>item.category===p.category).slice(0,5);
  const color=productColorName(Math.max(0,variants.findIndex(item=>item.id===p.id)));
  const profile=productProfile(p);
  if(state.productTab==='sizing'){
    if(shoeCategories.has(p.category)){
      const rows=[['38','24,5 см'],['39','25 см'],['40','25,5 см'],['41','26 см'],['42','27 см'],['43','27,5 см'],['44','28 см']];
      return `<div class="tab-copy"><h3>Размер и посадка</h3><p>Модель соответствует стандартной европейской размерной сетке. Если выбираете между двумя размерами, рекомендуем больший.</p><div class="size-guide">${rows.map(([size,length])=>`<div><b>${size}</b><span>Длина стопы</span><strong>${length}</strong></div>`).join('')}</div><p class="fit-note">Посадка: ${profile.fit}&nbsp;&nbsp;·&nbsp;&nbsp;${profile.details}</p></div>`;
    }
    if(clothingCategories.has(p.category)){
      const rows=[['S','44–46'],['M','48'],['L','50'],['XL','52'],['XXL','54–56']];
      return `<div class="tab-copy"><h3>Размер и посадка</h3><p>Выбирайте привычный размер. Для более свободного силуэта возьмите на один размер больше.</p><div class="size-guide">${rows.map(([size,ru])=>`<div><b>${size}</b><span>Российский размер</span><strong>${ru}</strong></div>`).join('')}</div><p class="fit-note">Посадка: ${profile.fit}&nbsp;&nbsp;·&nbsp;&nbsp;${profile.details}</p></div>`;
    }
    return `<div class="tab-copy"><h3>Размер и посадка</h3><p>${profile.fit}. ${profile.details}. Точные параметры можно уточнить перед заказом.</p></div>`;
  }
  if(state.productTab==='brand')return `<div class="tab-copy"><div class="product-brand-card"><strong>${p.brand}</strong><p>${brandDescription(p.brand)}</p></div><dl class="product-specs"><div><dt>Направление</dt><dd>Современный мужской гардероб</dd></div><div><dt>Коллекция</dt><dd>Основная линия</dd></div><div><dt>Страна дизайна</dt><dd>Италия</dd></div></dl></div>`;
  return `<p class="product-description">${profile.description}</p><dl class="product-specs"><div><dt>Бренд</dt><dd>${p.brand}</dd></div><div><dt>Категория</dt><dd>${p.category}</dd></div>${p.label&&p.label!==p.category?`<div><dt>Тип</dt><dd>${p.label}</dd></div>`:''}<div><dt>Цвет</dt><dd>${color}</dd></div><div><dt>Состав</dt><dd>${profile.material}</dd></div><div><dt>Посадка</dt><dd>${profile.fit}</dd></div><div><dt>Страна дизайна</dt><dd>Италия</dd></div><div><dt>Артикул</dt><dd>${String(p.id).padStart(7,'0')}</dd></div></dl>`;
}
function productView(){
  const p=products.find(x=>x.id===state.productId)||products[0];
  if(!p)return `${header(true)}<main class="empty-cart"><p>Загружаем товар…</p></main>${nav()}`;
  const variants=products.filter(item=>item.category===p.category).slice(0,5);
  const gallery=productGalleryImages(p);
  const sizes=productSizes(p);
  if(!sizes.includes(state.selectedSize))state.selectedSize=defaultProductSize(p);
  return `<header class="header product-header"><button class="icon-btn" data-action="back" aria-label="Назад">${icons.back}</button><span class="product-header__brand">${p.brand}</span><div class="header__actions"></div></header><main class="product-view"><section class="product-gallery"><div class="product-gallery__track" data-gallery>${gallery.map((image,index)=>`<div class="product-gallery__slide"><img src="${image}" alt="${p.name}, фото ${index+1}" draggable="false"></div>`).join('')}</div><div class="gallery-dots">${gallery.map((_,index)=>`<span class="${index===0?'active':''}" data-gallery-dot="${index}"></span>`).join('')}</div></section><section class="product-summary"><div class="product-summary__row"><button class="product-action" data-action="share" aria-label="Поделиться"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M12 16V3m0 0L8 7m4-4 4 4"/><path d="M6 10H4v10h16V10h-2"/></svg></button><div><h1>${p.brand}</h1><p>${p.name}</p><strong>${p.price}</strong></div><button class="product-action" data-favorite="${p.id}" aria-label="В избранное">${icons.star}</button></div></section><section class="product-options"><h2>Цвет</h2><div class="color-options">${variants.map((item,index)=>`<button class="color-option ${item.id===p.id?'active':''}" data-variant="${item.id}"><span><img src="${item.image}" alt="${productColorName(index)}"></span><small>${productColorName(index)}</small></button>`).join('')}</div><div class="size-heading"><h2>Размер</h2><button data-product-tab="sizing">Таблица размеров</button></div><div class="size-options">${sizes.map(size=>`<button class="size-option ${size===state.selectedSize?'active':''}" data-size="${size}"><b>${size}</b></button>`).join('')}</div></section><section class="product-details"><div class="detail-tabs"><button class="${state.productTab==='details'?'active':''}" data-product-tab="details">О товаре</button><button class="${state.productTab==='sizing'?'active':''}" data-product-tab="sizing">Размеры и посадка</button><button class="${state.productTab==='brand'?'active':''}" data-product-tab="brand">О бренде</button></div><div class="product-tab-panel">${productTabPanel(p)}</div><p class="breadcrumbs">Главная&nbsp;&nbsp;•&nbsp;&nbsp;Товары для мужчин&nbsp;&nbsp;•&nbsp;&nbsp;${p.category}&nbsp;&nbsp;•&nbsp;&nbsp;${p.label||p.name}</p><div class="product-links"><button data-browse-brand="${p.brand}">Все товары ${p.brand}</button><button data-browse-category="${p.category}">Все товары: ${p.category}</button><button data-page="catalog">Вернуться в каталог</button></div></section></main><div class="buy-bar product-buy-bar"><button class="quick-buy" data-action="quick-buy">Быстрая покупка</button><button class="primary-btn" data-add="${p.id}">${state.cart.includes(p.id)?'В корзине':'В корзину'}</button></div>${nav()}`;
}
function updateProductVariant(id){const p=products.find(item=>item.id===Number(id));if(!p)return;state.productId=p.id;const variants=products.filter(item=>item.category===p.category).slice(0,5);const gallery=productGalleryImages(p);document.querySelector('.product-header__brand').textContent=p.brand;const summary=document.querySelector('.product-summary');summary.querySelector('h1').textContent=p.brand;summary.querySelector('p').textContent=p.name;summary.querySelector('strong').textContent=p.price;summary.querySelector('[data-favorite]').dataset.favorite=p.id;document.querySelector('[data-gallery]').innerHTML=gallery.map((image,index)=>`<div class="product-gallery__slide"><img src="${image}" alt="${p.name}, фото ${index+1}" draggable="false"></div>`).join('');document.querySelector('.gallery-dots').innerHTML=gallery.map((_,index)=>`<span class="${index===0?'active':''}" data-gallery-dot="${index}"></span>`).join('');document.querySelectorAll('[data-variant]').forEach(button=>button.classList.toggle('active',Number(button.dataset.variant)===p.id));document.querySelector('.product-tab-panel').innerHTML=productTabPanel(p);document.querySelector('.breadcrumbs').innerHTML=`Главная&nbsp;&nbsp;•&nbsp;&nbsp;Товары для мужчин&nbsp;&nbsp;•&nbsp;&nbsp;${p.category}&nbsp;&nbsp;•&nbsp;&nbsp;${p.label||p.name}`;const links=document.querySelectorAll('.product-links button');links[0].textContent=`Все товары ${p.brand}`;links[0].dataset.browseBrand=p.brand;links[1].textContent=`Все товары: ${p.category}`;links[1].dataset.browseCategory=p.category;const add=document.querySelector('[data-add]');add.dataset.add=p.id;add.textContent=state.cart.includes(p.id)?'В корзине':'В корзину';enableProductGallery();}
function cart(){
  const items=state.cart.map(id=>products.find(p=>p.id===id)).filter(Boolean);
  const quantity=cartQuantity();
  return `${cartHeader()}<main class="cart">${items.length?`<p class="cart-count">${quantity} ${quantity===1?'товар':'товара'}</p>`+items.map(p=>{const details=state.cartDetails[p.id]||{quantity:1,size:defaultProductSize(p),color:currentProductColor(p)};return `<article class="cart-item" data-cart-item="${p.id}"><div class="cart-item__media"><img class="cart-item__image" src="${p.image}" alt="${p.name}"></div><div class="cart-item__copy"><div class="cart-item__title"><h3>${p.brand}</h3><strong>${lineTotal(p,details.quantity)} ₽</strong></div><p class="cart-item__name">${p.name}</p><p class="cart-item__selection">Размер ${details.size||defaultProductSize(p)}&nbsp;&nbsp;·&nbsp;&nbsp;${details.color}</p><div class="cart-item__actions"><div class="quantity-control" aria-label="Количество товара"><button data-quantity="-1" data-cart-id="${p.id}" aria-label="Уменьшить количество">−</button><span>${details.quantity}</span><button data-quantity="1" data-cart-id="${p.id}" aria-label="Увеличить количество">+</button></div><button class="remove-btn" data-remove="${p.id}">Удалить</button></div></div></article>`;}).join('')+`<div class="cart-summary"><div><span>Товары</span><span>${cartTotal()} ₽</span></div><div><span>Доставка</span><span>Рассчитаем позже</span></div><div class="total"><span>Итого</span><span>${cartTotal()} ₽</span></div></div><button class="primary-btn cart-checkout" data-action="checkout">Перейти к оформлению</button>`:`<div class="empty-cart"><h2>Корзина пока пуста</h2><p>Добавьте понравившиеся вещи из каталога</p><button class="primary-btn" data-page="catalog">Перейти в каталог</button></div>`}</main>${nav()}`;
}
function checkout(){
  const items=state.cart.map(id=>products.find(p=>p.id===id)).filter(Boolean);
  if(!items.length)return `${cartHeader()}<main class="empty-cart checkout-empty"><h2>Нечего оформлять</h2><p>Сначала добавьте товар в корзину</p><button class="primary-btn" data-page="catalog">Перейти в каталог</button></main>${nav()}`;
  const quantity=cartQuantity();
  return `${cartHeader().replace('<strong>Корзина</strong>','<strong>Оформление</strong>')}<main class="checkout-page"><section class="checkout-intro"><h1>Данные для заказа</h1><p>После отправки мы получим заказ и свяжемся с вами, чтобы обсудить все детали.</p></section><form class="checkout-form" data-checkout-form novalidate><div class="checkout-fields"><label><span>Имя</span><input name="name" autocomplete="name" placeholder="Как к вам обращаться" required></label><label><span>Телефон или Telegram</span><input name="contact" autocomplete="tel" placeholder="+7 999 000-00-00 или @username" required></label><label><span>Город</span><input name="city" autocomplete="address-level2" placeholder="Москва" required></label><label><span>Адрес</span><input name="address" autocomplete="street-address" placeholder="Улица, дом, квартира" required></label></div><label class="checkout-comment"><span>Комментарий</span><textarea name="comment" rows="3" placeholder="Пожелания к заказу"></textarea></label><div class="checkout-total"><span>${quantity} ${quantity===1?'товар':'товара'}</span><strong>${cartTotal()} ₽</strong></div><p class="checkout-error" role="alert" aria-live="polite"></p><button class="primary-btn checkout-submit" type="submit">Отправить заказ</button></form></main>${nav()}`;
}
function orderSuccess(){
  const order=state.order;
  if(!order)return `${cartHeader()}<main class="empty-cart"><h2>Заказ не найден</h2><button class="primary-btn" data-page="catalog">Перейти в каталог</button></main>${nav()}`;
  return `${cartHeader().replace('<strong>Корзина</strong>','<strong>Заказ оформлен</strong>')}<main class="order-success"><div class="order-success__mark">✓</div><p class="order-success__number">Заказ № ${order.number}</p><h1>Заявка отправлена</h1><p>Мы свяжемся с вами, чтобы подтвердить товары, стоимость и способ получения.</p><div class="order-success__summary"><span>${order.count} ${order.count===1?'товар':'товара'}</span><strong>${order.total} ₽</strong></div><button class="primary-btn" data-page="home">На главную</button><button class="secondary-btn" data-page="catalog">Продолжить покупки</button></main>${nav()}`;
}
function simplePage(title,text){return `${header(true)}<main class="empty-cart"><h2>${title}</h2><p>${text}</p><button class="secondary-btn" data-page="catalog">Перейти в каталог</button></main>${nav()}`;}
function support(){const topics=['Оплата','Как заказать','Доставка','Минимальный заказ'];return `${header(true)}<main class="information-page"><div class="page-title"><h1>Сервис</h1><p>Здесь появятся условия заказа и доставки</p></div><div class="information-topics">${topics.map(topic=>`<section class="information-topic"><h2>${topic}</h2><span>Информация появится позже</span></section>`).join('')}</div><section class="telegram-support"><div><h2>Нужна помощь?</h2><p>Напишите нам в Telegram</p></div><a href="https://t.me/nurmvoid" target="_blank" rel="noopener noreferrer">Перейти в Telegram</a></section></main>${nav()}`;}
function filterDrawer(){return `<div class="drawer-backdrop"><section class="drawer"><div class="drawer__head"><h2>Фильтры</h2><button class="icon-btn" data-action="close-drawer">${icons.close}</button></div>${['Категория','Бренд','Новинки','Премиум','Размер','Цвет','Материал','Утеплитель','Цена'].map(x=>`<button class="filter-row" data-filter-row="${x}"><span>${x}</span><span>+</span></button>`).join('')}<div class="drawer__footer"><button class="secondary-btn" data-action="reset-filter">Сбросить</button><button class="primary-btn" data-action="apply-filter">Показать ${products.length}</button></div></section></div>`;}
function productPrice(p){return Number(p.price.replace(/\D/g,''));}
function cartQuantity(){return state.cart.reduce((total,id)=>total+(state.cartDetails[id]?.quantity||1),0);}
function cartTotal(){return state.cart.reduce((total,id)=>{const product=products.find(item=>item.id===id);return total+(product?productPrice(product)*(state.cartDetails[id]?.quantity||1):0);},0).toLocaleString('ru-RU');}
function lineTotal(p,quantity){return (productPrice(p)*quantity).toLocaleString('ru-RU');}
function sum(items){return items.reduce((a,p)=>a+productPrice(p),0).toLocaleString('ru-RU');}
function productLabel(item){const labels={88:'Высокие кеды',89:'Спортивные кроссовки',90:'Кроссовки',92:'Кеды',93:'На каждый день',94:'Механические',95:'Классические',96:'С усложнениями',97:'Автоматические',98:'Спортивные'};return labels[item.id]||categoryNames[item.category]||item.title;}
function normalizeProduct(item){return {id:item.id,brand:(item.brand||'SELECTED').toUpperCase(),name:item.title,price:`${Math.round(item.price*1000).toLocaleString('ru-RU')} ₽`,image:item.thumbnail||item.images?.[0],images:item.images,category:categoryNames[item.category]||'Аксессуары',label:productLabel(item)};}
async function loadCatalog(){try{const data=await Promise.all(sourceCategories.map(c=>fetch(`https://dummyjson.com/products/category/${c}`).then(r=>{if(!r.ok)throw Error('catalog request failed');return r.json();})));const outerwear=[{id:1001,brand:'LIGNE',name:'Шерстяное мужское пальто',price:'189 000 ₽',image:'assets/outerwear-coat.png',category:'Верхняя одежда',label:'Пальто'},{id:1002,brand:'LIGNE',name:'Кожаная куртка',price:'214 000 ₽',image:'assets/outerwear-leather-jacket.png',category:'Верхняя одежда',label:'Кожаные куртки'},{id:1003,brand:'LIGNE',name:'Бомбер из технической ткани',price:'126 000 ₽',image:'assets/outerwear-bomber.png',category:'Верхняя одежда',label:'Бомберы'},{id:1004,brand:'ATELIER',name:'Полевая куртка из хлопка',price:'96 000 ₽',image:'assets/outerwear-field-jacket.png',category:'Верхняя одежда',label:'Ветровки'}];const bottoms=[{id:1101,brand:'LIGNE',name:'Прямые джинсы',price:'58 500 ₽',image:'assets/bottoms-jeans.png',category:'Брюки и джинсы',label:'Джинсы'},{id:1102,brand:'LIGNE',name:'Шерстяные брюки',price:'74 000 ₽',image:'assets/bottoms-trousers.png',category:'Брюки и джинсы',label:'Классические брюки'},{id:1103,brand:'LIGNE',name:'Хлопковые брюки карго',price:'52 500 ₽',image:'assets/bottoms-cargo.png',category:'Брюки и джинсы',label:'Карго'}];const clothing=[{id:1301,brand:'ATELIER',name:'Хлопковая рубашка',price:'46 000 ₽',image:'assets/clothing-shirt.png',category:'Одежда',label:'Рубашки'},{id:1302,brand:'ATELIER',name:'Базовая футболка',price:'21 000 ₽',image:'assets/clothing-tshirt.png',category:'Одежда',label:'Футболки'},{id:1303,brand:'ATELIER',name:'Рубашка с коротким рукавом',price:'29 000 ₽',image:'assets/clothing-short-sleeve.png',category:'Одежда',label:'Рубашки с коротким рукавом'},{id:1304,brand:'ATELIER',name:'Классическая хлопковая рубашка',price:'54 000 ₽',image:'assets/clothing-classic-shirt.png',category:'Одежда',label:'Классические рубашки'}];const watches=[{id:106,brand:'SELECTED',name:'Спортивные смарт-часы',price:'89 000 ₽',image:'https://cdn.dummyjson.com/product-images/mobile-accessories/apple-watch-series-4-gold/thumbnail.webp',category:'Часы',label:'Для бега'}];const accessories=[{id:1201,brand:'SELECTED',name:'Городской рюкзак',price:'42 000 ₽',image:'assets/accessory-backpack.png',category:'Аксессуары',label:'Рюкзаки'},{id:1202,brand:'ATELIER',name:'Кожаный ремень',price:'24 500 ₽',image:'assets/accessory-belt-white.jpg',category:'Аксессуары',label:'Ремни'},{id:1203,brand:'ATELIER',name:'Деловая мужская сумка',price:'68 000 ₽',image:'assets/accessory-business-bag.png',category:'Аксессуары',label:'Мужские сумки'}];products=[...outerwear,...extraOuterwearProducts,...bottoms,...clothing,...data.flatMap(g=>g.products).map(normalizeProduct),...watches,...accessories];products.forEach(product=>{product.image=productImages[product.id]||product.image;});state.productId||=products[0]?.id;}catch(error){console.error(error);toast('Не удалось загрузить каталог');}render();}
let suppressCatalogClick=false;
function enableCatalogDragging(){document.querySelectorAll('.catalog-category__track').forEach(track=>{let startX=0,startScroll=0,moved=false,dragging=false;track.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;dragging=true;moved=false;startX=e.clientX;startScroll=track.scrollLeft;});track.addEventListener('pointermove',e=>{if(!dragging)return;const distance=e.clientX-startX;if(!moved&&Math.abs(distance)>8){moved=true;track.setPointerCapture(e.pointerId);track.classList.add('is-dragging');}if(moved){track.scrollLeft=startScroll-distance;e.preventDefault();}});const finish=e=>{if(!dragging)return;dragging=false;track.classList.remove('is-dragging');if(track.hasPointerCapture(e.pointerId))track.releasePointerCapture(e.pointerId);if(moved){suppressCatalogClick=true;setTimeout(()=>{suppressCatalogClick=false;},60);}};track.addEventListener('pointerup',finish);track.addEventListener('pointercancel',finish);track.addEventListener('wheel',e=>{if(Math.abs(e.deltaX)>Math.abs(e.deltaY)||e.shiftKey)return;if(track.scrollWidth<=track.clientWidth)return;}, {passive:true});});}
function enableTouchHorizontalScrolling(){document.querySelectorAll('.catalog-category__track,.category-row,.category-chips,.color-options,.size-options').forEach(track=>{let startX=0,startY=0,startScroll=0,tracking=false,horizontal=false,suppressClick=false;track.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch')return;startX=e.clientX;startY=e.clientY;startScroll=track.scrollLeft;tracking=true;horizontal=false;});track.addEventListener('pointermove',e=>{if(!tracking)return;const dx=e.clientX-startX,dy=e.clientY-startY,ax=Math.abs(dx),ay=Math.abs(dy);if(!horizontal){if(ay>=10&&ay>=ax*.75){tracking=false;return;}if(ax<18||ax<ay*1.7)return;horizontal=true;track.setPointerCapture(e.pointerId);}track.scrollLeft=startScroll-dx;e.preventDefault();});const finish=e=>{if(horizontal){suppressClick=true;setTimeout(()=>{suppressClick=false;},350);if(track.hasPointerCapture(e.pointerId))track.releasePointerCapture(e.pointerId);}tracking=false;horizontal=false;};track.addEventListener('pointerup',finish);track.addEventListener('pointercancel',finish);track.addEventListener('click',e=>{if(!suppressClick)return;e.preventDefault();e.stopPropagation();suppressClick=false;},true);});}
function enableListingLinks(){document.querySelectorAll('[data-listing-category],[data-listing-label]').forEach(card=>card.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();if(suppressCatalogClick){suppressCatalogClick=false;return;}if(card.dataset.listingCategory){state.listingMode='category';state.listingCategory=card.dataset.listingCategory;}else{state.listingMode='label';state.listingLabel=card.dataset.listingLabel;}go('listing');}));}
function enableProductGallery(){const track=document.querySelector('[data-gallery]');if(!track)return;let frame=0,startX=0,startY=0,startScroll=0,tracking=false,horizontal=false;track.addEventListener('scroll',()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const index=Math.round(track.scrollLeft/track.clientWidth);document.querySelectorAll('[data-gallery-dot]').forEach((dot,dotIndex)=>dot.classList.toggle('active',dotIndex===index));});},{passive:true});track.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch')return;startX=e.clientX;startY=e.clientY;startScroll=track.scrollLeft;tracking=true;horizontal=false;});track.addEventListener('pointermove',e=>{if(!tracking)return;const dx=e.clientX-startX,dy=e.clientY-startY,ax=Math.abs(dx),ay=Math.abs(dy);if(!horizontal){if(ay>=10&&ay>=ax*.75){tracking=false;return;}if(ax<18||ax<ay*1.7)return;horizontal=true;track.setPointerCapture(e.pointerId);}track.scrollLeft=startScroll-dx;e.preventDefault();});const finish=e=>{if(!tracking&&!horizontal)return;if(horizontal){const index=Math.round(track.scrollLeft/track.clientWidth);track.scrollTo({left:index*track.clientWidth,behavior:'smooth'});if(track.hasPointerCapture(e.pointerId))track.releasePointerCapture(e.pointerId);}tracking=false;horizontal=false;};track.addEventListener('pointerup',finish);track.addEventListener('pointercancel',finish);}
function enableDrawerBackdrop(){const backdrop=document.querySelector('.drawer-backdrop');if(!backdrop)return;backdrop.addEventListener('click',e=>{if(e.target!==backdrop)return;state.drawer=false;render();});}
function preserveBottomNav(current,next){const currentItems=[...current.children].filter(item=>item.matches('button,a'));const nextItems=[...next.children].filter(item=>item.matches('button,a'));currentItems.forEach((item,index)=>{const fresh=nextItems[index];item.className=fresh.className;item.innerHTML=fresh.innerHTML;if(fresh.hasAttribute('aria-current'))item.setAttribute('aria-current','page');else item.removeAttribute('aria-current');});current.dataset.navIndex=next.dataset.navIndex;next.replaceWith(current);return current;}
function moveNavIndicator(nav,nextIndex,animated){const indicator=nav.querySelector('.bottom-nav__indicator');if(!indicator)return;clearTimeout(indicator._moveTimer);const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;const currentTransform=getComputedStyle(indicator).transform;indicator.style.transition='none';indicator.style.transform=currentTransform;indicator.getBoundingClientRect();nav.style.setProperty('--nav-index',nextIndex);if(!animated||reduceMotion){indicator.style.transform='';requestAnimationFrame(()=>{indicator.style.transition='';});return;}const targetX=indicator.getBoundingClientRect().width*(2/3)*nextIndex;requestAnimationFrame(()=>{indicator.style.transition='transform 460ms cubic-bezier(.22,1,.36,1)';indicator.getBoundingClientRect();indicator.style.transform=`translateX(${targetX}px)`;indicator._moveTimer=setTimeout(()=>{indicator.style.transition='none';indicator.style.transform='';indicator.getBoundingClientRect();indicator.style.transition='';},480);});}
function render({preserveScroll=false,animate=false,direction='forward'}={}){const scrollTop=window.scrollY;const pages={home,catalog,listing,search,product:productView,cart,checkout,'order-success':orderSuccess,support};const app=document.querySelector('#app');const currentNav=app.querySelector('.bottom-nav');if(currentNav)document.body.appendChild(currentNav);app.innerHTML=(pages[state.page]||home)();enableCatalogDragging();enableTouchHorizontalScrolling();enableListingLinks();enableProductGallery();enableDrawerBackdrop();let nav=app.querySelector('.bottom-nav');if(currentNav&&nav)nav=preserveBottomNav(currentNav,nav);if(nav){const nextIndex=Number(nav.dataset.navIndex);moveNavIndicator(nav,nextIndex,Boolean(currentNav));navVisualIndex=nextIndex;}if(animate)app.querySelector(':scope > main')?.classList.add('page-enter',`page-enter--${direction}`);if(preserveScroll){requestAnimationFrame(()=>requestAnimationFrame(()=>window.scrollTo(0,scrollTop)));}else{window.scrollTo(0,0);}}
function pageRank(page){return navPages.indexOf(activeNavPage(page));}
function changePage(update,direction){const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;const current=document.querySelector('#app > main');if(reduceMotion||!current){update(false);return;}current.getAnimations().forEach(animation=>animation.cancel());const rect=current.getBoundingClientRect();const distance=direction==='forward'?-12:12;current.classList.add('page-leave-layer');Object.assign(current.style,{top:`${rect.top}px`,left:`${rect.left}px`,width:`${rect.width}px`,height:`${Math.max(0,innerHeight-rect.top-64)}px`});document.body.appendChild(current);update(true);const exit=current.animate([{opacity:1,transform:'translateX(0)'},{opacity:0,transform:`translateX(${distance}px)`}],{duration:320,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'});exit.finished.then(()=>current.remove()).catch(()=>current.remove());}
function go(page){const direction=pageRank(page)>=pageRank(state.page)?'forward':'back';changePage(animate=>{state.page=page;state.drawer=false;history.pushState({page,listingMode:state.listingMode,listingCategory:state.listingCategory,listingBrand:state.listingBrand,listingLabel:state.listingLabel},'',`${location.pathname}#${page}`);render({animate,direction});},direction);}
function toast(message,duration=1800){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),duration);}
function showLaunchIntro(){
  const overlay=document.createElement('div');
  overlay.className='launch-screen';
  overlay.setAttribute('aria-hidden','true');
  overlay.innerHTML='<div class="launch-curtain"></div>';
  document.body.appendChild(overlay);
  const target=document.querySelector('.header__logo,.men-brand');
  const targetHeader=target?.closest('.header,.men-header');
  const finish=()=>{};
  const abort=()=>{targetHeader?.classList.remove('launch-header-active');overlay.remove();};
  if(matchMedia('(prefers-reduced-motion: reduce)').matches){setTimeout(abort,180);return;}
  const start=()=>requestAnimationFrame(()=>{
    const curtain=overlay.querySelector('.launch-curtain');
    if(!target||!targetHeader){abort();return;}
    const targetRect=target.getBoundingClientRect();
    const targetStyle=getComputedStyle(target);
    const dx=innerWidth/2-(targetRect.left+targetRect.width/2);
    const dy=innerHeight/2-(targetRect.top+targetRect.height/2);
    const finalFontSize=parseFloat(targetStyle?.fontSize)||18;
    const startScale=21/finalFontSize;
    const centerTransform=`translate(${dx}px,${dy}px) scale(${startScale})`;
    const endTransform='translate(0,0) scale(1)';
    const wait=duration=>new Promise(resolve=>setTimeout(resolve,duration));
    const run=async()=>{
      targetHeader.classList.add('launch-header-active');
      const appear=target.animate([
        {transform:centerTransform,opacity:0},
        {transform:centerTransform,opacity:1}
      ],{duration:420,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'});
      await appear.finished;
      await wait(180);
      const flightDuration=86400000;
      const landingOffset=950/flightDuration;
      const flight=target.animate([
        {transform:centerTransform,offset:0,easing:'cubic-bezier(.4,0,.2,1)'},
        {transform:endTransform,offset:landingOffset},
        {transform:endTransform,offset:1}
      ],{duration:flightDuration,easing:'linear',fill:'forwards'});
      await wait(950);
      const curtainFade=curtain.animate([{opacity:1},{opacity:0}],{duration:520,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'});
      const headerFade=targetHeader.animate([
        {backgroundColor:'rgba(255,255,255,0)',borderColor:'rgba(236,236,234,0)'},
        {backgroundColor:'rgba(255,255,255,.96)',borderColor:'rgba(236,236,234,1)'}
      ],{duration:520,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'});
      const headerItems=[...targetHeader.children].filter(item=>item!==target);
      const itemFades=headerItems.map(item=>item.animate([{opacity:0},{opacity:1}],{duration:520,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'}));
      await Promise.all([curtainFade.finished,headerFade.finished,...itemFades.map(animation=>animation.finished)]);
      finish();
    };
    run().catch(abort);
  });
  if(document.fonts?.ready)document.fonts.ready.then(start).catch(start);else start();
}
async function shareProduct(){const url=location.href;try{if(navigator.share){await navigator.share({title:document.querySelector('.product-summary h1')?.textContent?.trim()||document.title,url});return;}await navigator.clipboard.writeText(url);toast('Ссылка скопирована');}catch(error){if(error?.name!=='AbortError')toast('Не удалось поделиться ссылкой');}}

