document.addEventListener('click',e=>{const button=e.target.closest('[data-remove]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const id=Number(button.dataset.remove);state.cart=state.cart.filter(itemId=>itemId!==id);delete state.cartDetails[id];persistCart();render({preserveScroll:true});},true);
